-fn is_definition(before: &str, after: &str) -> bool {
+/// Whether the text `before` and `after` the literal make it a definition. In
+/// a Go file (`go_receivers`) a receiver `func (s *Server) ` before the name
+/// counts as the `func` keyword.
+fn is_definition(before: &str, after: &str, go_receivers: bool) -> bool {
     if !before.ends_with(is_blank) {
         return false;
     }
-    let head = before.trim_end_matches(is_blank);
+    let mut head = before.trim_end_matches(is_blank);
+    let mut receiver = false;
+    if go_receivers && head.ends_with(')') {
+        let Some(prefix) = go_receiver_prefix(head) else {
+            return false;
+        };
+        head = prefix;
+        receiver = true;
+    }
     let word_start = head
         .trim_end_matches(|c: char| c.is_ascii_alphabetic())
         .len();
+    let keyword = &head[word_start..];
     let stands_alone = head[..word_start].is_empty() || head[..word_start].ends_with(is_blank);
     stands_alone
-        && DEFINITION_KEYWORDS.contains(&&head[word_start..])
+        && DEFINITION_KEYWORDS.contains(&keyword)
+        && (!receiver || keyword == "func")
         && !after.starts_with(|c: char| c.is_ascii_alphanumeric() || c == '_')
 }

+/// The text before the receiver of `head`, which ends with `(...)`, without
+/// the blanks between them; none when no blank separates it from the text.
+fn go_receiver_prefix(head: &str) -> Option<&str> {
+    let (prefix, _receiver) = head.strip_suffix(')')?.rsplit_once('(')?;
+    prefix
+        .ends_with(is_blank)
+        .then(|| prefix.trim_end_matches(is_blank))
+}
